CREATE TABLE IF NOT EXISTS manufacturers (id BIGSERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL, country TEXT DEFAULT '', details TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS suppliers (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, unp TEXT DEFAULT '', phone TEXT DEFAULT '', email TEXT DEFAULT '', address TEXT DEFAULT '', notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS customers (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, unp TEXT DEFAULT '', address TEXT DEFAULT '', phone TEXT DEFAULT '', email TEXT DEFAULT '', bank_details TEXT DEFAULT '', notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS products (id BIGSERIAL PRIMARY KEY, article TEXT UNIQUE NOT NULL, name TEXT NOT NULL, category TEXT DEFAULT '', tnved TEXT DEFAULT '', manufacturer_id BIGINT REFERENCES manufacturers(id), unit TEXT DEFAULT 'шт', vat NUMERIC(8,3) DEFAULT 20, purchase_price NUMERIC(16,4) DEFAULT 0, sale_price NUMERIC(16,4) DEFAULT 0, notes TEXT DEFAULT '', active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS certificates (id BIGSERIAL PRIMARY KEY, number TEXT UNIQUE NOT NULL, doc_type TEXT DEFAULT 'Сертификат', manufacturer_id BIGINT REFERENCES manufacturers(id), issue_date TEXT DEFAULT '', expiry_date TEXT DEFAULT '', file_path TEXT DEFAULT '', status TEXT DEFAULT 'На проверке', notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS product_certificates (product_id BIGINT REFERENCES products(id) ON DELETE CASCADE, certificate_id BIGINT REFERENCES certificates(id) ON DELETE CASCADE, PRIMARY KEY(product_id,certificate_id));
CREATE TABLE IF NOT EXISTS certificate_catalog_items (id BIGSERIAL PRIMARY KEY, certificate_number TEXT NOT NULL, expiry_date TEXT DEFAULT '', product_code TEXT DEFAULT '', description TEXT NOT NULL, tnved TEXT DEFAULT '', review_status TEXT DEFAULT 'На проверке', product_id BIGINT REFERENCES products(id), UNIQUE(certificate_number,product_code,description));
CREATE TABLE IF NOT EXISTS certificate_files (id BIGSERIAL PRIMARY KEY, certificate_id BIGINT REFERENCES certificates(id), original_name TEXT NOT NULL, stored_name TEXT NOT NULL, extracted_text TEXT DEFAULT '', uploaded_at TIMESTAMP DEFAULT NOW(), file_data BYTEA);
CREATE TABLE IF NOT EXISTS warehouses (id BIGSERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL, address TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS batches (id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id), warehouse_id BIGINT NOT NULL REFERENCES warehouses(id), supplier_id BIGINT REFERENCES suppliers(id), batch_code TEXT DEFAULT '', received_at TEXT DEFAULT '', qty_initial NUMERIC(18,4) NOT NULL DEFAULT 0, qty_remaining NUMERIC(18,4) NOT NULL DEFAULT 0, purchase_price NUMERIC(16,4) DEFAULT 0, certificate_id BIGINT REFERENCES certificates(id), notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS movements (id BIGSERIAL PRIMARY KEY, kind TEXT NOT NULL, product_id BIGINT NOT NULL REFERENCES products(id), warehouse_id BIGINT NOT NULL REFERENCES warehouses(id), batch_id BIGINT REFERENCES batches(id), qty NUMERIC(18,4) NOT NULL, unit_price NUMERIC(16,4) DEFAULT 0, ref TEXT DEFAULT '', party TEXT DEFAULT '', created_at TIMESTAMP DEFAULT NOW(), notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS documents (id BIGSERIAL PRIMARY KEY, doc_no TEXT DEFAULT '', doc_date TEXT DEFAULT '', customer_id BIGINT REFERENCES customers(id), status TEXT DEFAULT 'Черновик', doc_type TEXT DEFAULT 'Счёт', created_at TIMESTAMP DEFAULT NOW(), notes TEXT DEFAULT '', warehouse_id BIGINT REFERENCES warehouses(id));
CREATE TABLE IF NOT EXISTS document_items (id BIGSERIAL PRIMARY KEY, document_id BIGINT NOT NULL REFERENCES documents(id) ON DELETE CASCADE, product_id BIGINT NOT NULL REFERENCES products(id), batch_id BIGINT, article TEXT, name TEXT, tnved TEXT, manufacturer TEXT, certificate TEXT, qty NUMERIC(18,4), price NUMERIC(16,4), vat NUMERIC(8,3));
CREATE TABLE IF NOT EXISTS audit_log (id BIGSERIAL PRIMARY KEY, action TEXT, entity TEXT, entity_id BIGINT, details TEXT, created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, salt TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'operator', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions (id BIGSERIAL PRIMARY KEY, token_hash TEXT UNIQUE NOT NULL, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS document_allocations (id BIGSERIAL PRIMARY KEY, document_item_id BIGINT NOT NULL REFERENCES document_items(id) ON DELETE CASCADE, batch_id BIGINT NOT NULL REFERENCES batches(id), qty NUMERIC(18,4) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_products_article ON products(article);
CREATE INDEX IF NOT EXISTS idx_catalog_search ON certificate_catalog_items(product_code, certificate_number);
CREATE INDEX IF NOT EXISTS idx_batches_stock ON batches(product_id,warehouse_id,received_at,id);
CREATE INDEX IF NOT EXISTS idx_movements_created ON movements(created_at DESC);
